package com.minimapzoomcontrols;

import java.awt.Point;
import java.awt.Rectangle;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ControlBoundsTest
{
	private static final Rectangle MINIMAP = new Rectangle(600, 10, 152, 152);
	private static final double DELTA = 1e-9;

	private static ControlBounds buttons(ControlAnchor anchor, ControlLayout arrangement)
	{
		return ControlBounds.layout(MINIMAP, anchor, arrangement, ControlStyle.BUTTONS, 20, 64, 0, 0);
	}

	private static ControlBounds slider(ControlLayout arrangement)
	{
		return ControlBounds.layout(MINIMAP, ControlAnchor.BELOW, arrangement, ControlStyle.SLIDER, 20, 64, 0, 0);
	}

	@Test
	public void putsZoomOutOnTheLeftWhenSideBySide()
	{
		ControlBounds bounds = buttons(ControlAnchor.TOP_LEFT, ControlLayout.HORIZONTAL);

		assertEquals(new Rectangle(600, 10, 20, 20), bounds.getButtons().get(ZoomControl.OUT));
		assertEquals(new Rectangle(623, 10, 20, 20), bounds.getButtons().get(ZoomControl.IN));
		assertNull(bounds.getTrack());
	}

	@Test
	public void stacksZoomInAboveZoomOut()
	{
		ControlBounds bounds = buttons(ControlAnchor.TOP_LEFT, ControlLayout.VERTICAL);

		assertEquals(new Rectangle(600, 10, 20, 20), bounds.getButtons().get(ZoomControl.IN));
		assertEquals(new Rectangle(600, 33, 20, 20), bounds.getButtons().get(ZoomControl.OUT));
	}

	@Test
	public void keepsTheWholeBlockInsideTheAnchoredCorner()
	{
		ControlBounds bounds = buttons(ControlAnchor.BOTTOM_RIGHT, ControlLayout.VERTICAL);

		assertEquals(new Rectangle(732, 119, 20, 20), bounds.getButtons().get(ZoomControl.IN));
		assertEquals(new Rectangle(732, 142, 20, 20), bounds.getButtons().get(ZoomControl.OUT));
	}

	@Test
	public void centresBelowTheMinimap()
	{
		ControlBounds bounds = buttons(ControlAnchor.BELOW, ControlLayout.HORIZONTAL);
		Rectangle out = bounds.getButtons().get(ZoomControl.OUT);
		Rectangle in = bounds.getButtons().get(ZoomControl.IN);

		// within a pixel — an odd leftover width cannot be split evenly
		assertEquals(MINIMAP.getCenterX(), (out.x + in.x + in.width) / 2d, 1d);
		assertTrue(out.y >= MINIMAP.y + MINIMAP.height);
	}

	@Test
	public void seatsTheTrackBetweenTheTwoButtons()
	{
		ControlBounds bounds = slider(ControlLayout.HORIZONTAL);
		Rectangle out = bounds.getButtons().get(ZoomControl.OUT);
		Rectangle track = bounds.getTrack();
		Rectangle in = bounds.getButtons().get(ZoomControl.IN);

		assertEquals(64, track.width);
		assertEquals(out.x + out.width + 3, track.x);
		assertEquals(track.x + track.width + 3, in.x);
	}

	@Test
	public void readsTheFractionAlongAHorizontalTrack()
	{
		ControlBounds bounds = slider(ControlLayout.HORIZONTAL);
		Rectangle track = bounds.getTrack();

		assertEquals(0d, bounds.fractionAt(new Point(track.x, track.y)), DELTA);
		assertEquals(0.5d, bounds.fractionAt(new Point(track.x + track.width / 2, track.y)), DELTA);
		assertEquals(1d, bounds.fractionAt(new Point(track.x + track.width, track.y)), DELTA);
	}

	@Test
	public void readsAVerticalTrackFromTheBottomUp()
	{
		ControlBounds bounds = slider(ControlLayout.VERTICAL);
		Rectangle track = bounds.getTrack();

		assertEquals(0d, bounds.fractionAt(new Point(track.x, track.y + track.height)), DELTA);
		assertEquals(1d, bounds.fractionAt(new Point(track.x, track.y)), DELTA);
	}

	@Test
	public void clampsPointsPastTheEndsOfTheTrack()
	{
		ControlBounds bounds = slider(ControlLayout.HORIZONTAL);
		Rectangle track = bounds.getTrack();

		assertEquals(0d, bounds.fractionAt(new Point(track.x - 500, track.y)), DELTA);
		assertEquals(1d, bounds.fractionAt(new Point(track.x + 500, track.y)), DELTA);
	}

	@Test
	public void keepsTheHandleWithinTheTrackAsItTravels()
	{
		ControlBounds bounds = slider(ControlLayout.HORIZONTAL);
		Rectangle track = bounds.getTrack();
		Rectangle far = bounds.handleAt(1d);

		assertEquals(track.x, bounds.handleAt(0d).x);
		assertEquals(track.x + track.width, far.x + far.width);

		// it stands proud of the groove across the short axis, like the game's own
		Rectangle middle = bounds.handleAt(0.5d);
		assertTrue(middle.x > track.x && middle.x + middle.width < track.x + track.width);
		assertTrue(middle.y < track.y);
		assertTrue(middle.y + middle.height > track.y + track.height);
	}

	@Test
	public void reportsNoTrackWhenTheStyleIsButtonsOnly()
	{
		ControlBounds bounds = buttons(ControlAnchor.BELOW, ControlLayout.HORIZONTAL);

		assertFalse(bounds.trackContains(new Point(MINIMAP.x, MINIMAP.y)));
		assertNull(bounds.handleAt(0.5d));
	}

	@Test
	public void emptyBoundsMatchNothing()
	{
		assertNull(ControlBounds.empty().controlAt(new Point(0, 0)));
		assertFalse(ControlBounds.empty().trackContains(new Point(0, 0)));
	}
}

package com.minimapzoomcontrols;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class MinimapZoomTest
{
	private static final double DELTA = 1e-9;

	@Test
	public void stepsAWholeStepFromTheDefault()
	{
		assertEquals(4.5d, ZoomControl.IN.step(MinimapZoom.DEFAULT, 0.5d), DELTA);
		assertEquals(3.5d, ZoomControl.OUT.step(MinimapZoom.DEFAULT, 0.5d), DELTA);
	}

	@Test
	public void snapsOffGridZoomToTheStepGrid()
	{
		assertEquals(4.5d, ZoomControl.IN.step(4.37d, 0.5d), DELTA);
		assertEquals(4d, ZoomControl.OUT.step(4.37d, 0.5d), DELTA);
	}

	@Test
	public void clampsToTheSupportedRange()
	{
		assertEquals(MinimapZoom.MAX, ZoomControl.IN.step(MinimapZoom.MAX, 1d), DELTA);
		assertEquals(MinimapZoom.MIN, ZoomControl.OUT.step(MinimapZoom.MIN, 1d), DELTA);
	}

	@Test
	public void reportsWhenAControlHasNothingLeftToDo()
	{
		assertTrue(ZoomControl.IN.isAvailable(MinimapZoom.DEFAULT));
		assertTrue(ZoomControl.OUT.isAvailable(MinimapZoom.DEFAULT));
		assertFalse(ZoomControl.IN.isAvailable(MinimapZoom.MAX));
		assertFalse(ZoomControl.OUT.isAvailable(MinimapZoom.MIN));
	}

	@Test
	public void mapsTheSliderEndsToTheZoomLimits()
	{
		assertEquals(0d, MinimapZoom.fraction(MinimapZoom.MIN), DELTA);
		assertEquals(1d, MinimapZoom.fraction(MinimapZoom.MAX), DELTA);
		assertEquals(MinimapZoom.MIN, MinimapZoom.fromFraction(0d), DELTA);
		assertEquals(MinimapZoom.MAX, MinimapZoom.fromFraction(1d), DELTA);
	}

	@Test
	public void putsTheDefaultZoomHalfwayAlongTheSlider()
	{
		// 2 to 8 is two doublings and the default is the first of them, so a log
		// scale should land it dead centre rather than the third a linear track
		// would give
		assertEquals(0.5d, MinimapZoom.fraction(MinimapZoom.DEFAULT), DELTA);
	}

	@Test
	public void sliderPositionRoundTrips()
	{
		assertEquals(6d, MinimapZoom.fromFraction(MinimapZoom.fraction(6d)), DELTA);
	}

	@Test
	public void clampsSliderPositionsPastTheEnds()
	{
		assertEquals(MinimapZoom.MIN, MinimapZoom.fromFraction(-2d), DELTA);
		assertEquals(MinimapZoom.MAX, MinimapZoom.fromFraction(4d), DELTA);
	}

	@Test
	public void steppingIsReversible()
	{
		double zoom = MinimapZoom.DEFAULT;
		for (int i = 0; i < 5; i++)
		{
			zoom = ZoomControl.IN.step(zoom, 0.25d);
		}
		for (int i = 0; i < 5; i++)
		{
			zoom = ZoomControl.OUT.step(zoom, 0.25d);
		}

		assertEquals(MinimapZoom.DEFAULT, zoom, DELTA);
	}
}

package com.minimapzoomcontrols;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Renders the overlay's own drawing code to a PNG so the styling can be eyeballed
 * without booting a client. Run with: ./gradlew runStylePreview
 */
public class StylePreview
{
	private static final int CELL_WIDTH = 260;
	private static final int CELL_HEIGHT = 240;
	private static final int MAP_SIZE = 152;

	public static void main(String[] args) throws Exception
	{
		BufferedImage image = new BufferedImage(CELL_WIDTH * 2, CELL_HEIGHT * 2, BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		graphics.setColor(new Color(12, 10, 8));
		graphics.fillRect(0, 0, image.getWidth(), image.getHeight());

		cell(graphics, 0, 0, ControlStyle.BUTTONS, ControlLayout.HORIZONTAL, ControlAnchor.BELOW, false);
		cell(graphics, 1, 0, ControlStyle.SLIDER, ControlLayout.HORIZONTAL, ControlAnchor.BELOW, false);
		cell(graphics, 0, 1, ControlStyle.BUTTONS, ControlLayout.HORIZONTAL, ControlAnchor.BELOW, true);
		cell(graphics, 1, 1, ControlStyle.SLIDER, ControlLayout.VERTICAL, ControlAnchor.BOTTOM_RIGHT, false);

		graphics.dispose();

		File out = new File(args.length > 0 ? args[0] : "build/style-preview.png");
		ImageIO.write(scaled(image, 3), "png", out);
		System.out.println("wrote " + out.getAbsolutePath());
	}

	private static void cell(Graphics2D graphics, int column, int row, ControlStyle style, ControlLayout layout,
		ControlAnchor anchor, boolean hovered) throws Exception
	{
		Rectangle map = new Rectangle(column * CELL_WIDTH + (CELL_WIDTH - MAP_SIZE) / 2, row * CELL_HEIGHT + 20,
			MAP_SIZE, MAP_SIZE);

		// stand-in for the minimap so the controls can be judged against it
		graphics.setColor(new Color(38, 34, 28));
		graphics.fillOval(map.x, map.y, map.width, map.height);
		graphics.setColor(new Color(70, 63, 50));
		graphics.drawOval(map.x, map.y, map.width, map.height);

		PreviewConfig config = new PreviewConfig(style, layout, anchor);
		MinimapZoomControlsOverlay overlay = new MinimapZoomControlsOverlay(
			previewClient(map, hovered ? hoverPoint(map, config) : new Point(-1, -1)), config, new TooltipManager());

		overlay.render(graphics);
	}

	/**
	 * Nearest neighbour blow-up, so the preview shows the pixels the game would
	 * actually get rather than a resampled approximation of them.
	 */
	private static BufferedImage scaled(BufferedImage source, int factor)
	{
		BufferedImage target = new BufferedImage(source.getWidth() * factor, source.getHeight() * factor,
			BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = target.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		graphics.drawImage(source, 0, 0, target.getWidth(), target.getHeight(), null);
		graphics.dispose();
		return target;
	}

	private static Point hoverPoint(Rectangle map, PreviewConfig config)
	{
		ControlBounds bounds = ControlBounds.layout(map, config.anchor(), config.layout(), config.style(),
			config.buttonSize(), config.sliderLength(), config.xOffset(), config.yOffset());
		Rectangle button = bounds.getButtons().get(ZoomControl.IN);
		return new Point(button.x + button.width / 2, button.y + button.height / 2);
	}

	private static Client previewClient(Rectangle map, Point mouse)
	{
		Widget widget = mock(Widget.class);
		when(widget.isHidden()).thenReturn(false);
		when(widget.getBounds()).thenReturn(map);

		Client client = mock(Client.class);
		when(client.getWidget(anyInt())).thenReturn(widget);
		when(client.getMinimapZoom()).thenReturn(6d);
		when(client.getMouseCanvasPosition()).thenReturn(mouse);
		return client;
	}

	private static final class PreviewConfig implements MinimapZoomControlsConfig
	{
		private final ControlStyle style;
		private final ControlLayout layout;
		private final ControlAnchor anchor;

		private PreviewConfig(ControlStyle style, ControlLayout layout, ControlAnchor anchor)
		{
			this.style = style;
			this.layout = layout;
			this.anchor = anchor;
		}

		@Override
		public ControlStyle style()
		{
			return style;
		}

		@Override
		public ControlLayout layout()
		{
			return layout;
		}

		@Override
		public ControlAnchor anchor()
		{
			return anchor;
		}
	}
}

