package com.minimapzoomcontrols;

/**
 * Minimap zoom is measured in pixels per tile, with 4 being the game default.
 * Larger means more zoomed in.
 *
 * The client clamps to 2..8 itself and ignores anything outside that, so these
 * limits have to agree with it: set them wider and the controls keep offering
 * travel that writes through to nothing. Measured against a live client rather
 * than read off the source, since the clamp lives in the injected client.
 */
final class MinimapZoom
{
	static final double DEFAULT = 4d;
	static final double MIN = 2d;
	static final double MAX = 8d;

	private static final double EPSILON = 1e-6;

	private MinimapZoom()
	{
	}

	static double clamp(double zoom)
	{
		return Math.max(MIN, Math.min(MAX, zoom));
	}

	/**
	 * Moves one step along a grid of multiples of {@code stepSize}. The scroll
	 * wheel leaves the zoom on arbitrary values, so snapping to the grid keeps
	 * button presses landing on round numbers instead of carrying the remainder
	 * forever.
	 */
	static double step(double zoom, double stepSize, int direction)
	{
		double steps = zoom / stepSize;
		double target = direction > 0
			? Math.floor(steps + EPSILON) + 1
			: Math.ceil(steps - EPSILON) - 1;
		return clamp(target * stepSize);
	}

	static boolean canStep(double zoom, int direction)
	{
		return direction > 0 ? zoom < MAX - EPSILON : zoom > MIN + EPSILON;
	}

	/**
	 * Where a zoom level sits along the slider, from 0 fully out to 1 fully in.
	 * Zoom doubles rather than adds — going 2 to 3 is a far bigger change on
	 * screen than 7 to 8 — so the track is mapped logarithmically to keep a
	 * pixel of drag worth about the same wherever you grab it. It also lands the
	 * default at the middle of the track.
	 */
	static double fraction(double zoom)
	{
		return (log2(clamp(zoom)) - log2(MIN)) / (log2(MAX) - log2(MIN));
	}

	static double fromFraction(double fraction)
	{
		double travel = Math.max(0d, Math.min(1d, fraction));
		return clamp(Math.pow(2d, log2(MIN) + travel * (log2(MAX) - log2(MIN))));
	}

	private static double log2(double value)
	{
		return Math.log(value) / Math.log(2d);
	}
}

