package com.minimapzoomcontrols;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(MinimapZoomControlsConfig.GROUP)
public interface MinimapZoomControlsConfig extends Config
{
	String GROUP = "minimapzoomcontrols";

	@ConfigSection(
		name = "Appearance",
		description = "Where the buttons sit and how they look.",
		position = 10
	)
	String appearanceSection = "appearanceSection";

	@ConfigSection(
		name = "Keyboard",
		description = "Optional hotkeys, for zooming without the mouse at all.",
		position = 20,
		closedByDefault = true
	)
	String keyboardSection = "keyboardSection";

	@ConfigItem(
		keyName = "style",
		name = "Controls",
		description = "Buttons on their own, or a slider with a button at each end.",
		position = 0
	)
	default ControlStyle style()
	{
		return ControlStyle.BUTTONS;
	}

	@ConfigItem(
		keyName = "zoomStep",
		name = "Step size",
		description = "How much one button press changes the zoom by.",
		position = 1
	)
	default ZoomStep zoomStep()
	{
		return ZoomStep.FINE;
	}

	@ConfigItem(
		keyName = "showTooltips",
		name = "Show tooltips",
		description = "Show the current zoom level when hovering the controls.",
		position = 2
	)
	default boolean showTooltips()
	{
		return false;
	}

	@ConfigItem(
		keyName = "anchor",
		name = "Position",
		description = "Where the controls sit relative to the minimap.",
		position = 0,
		section = appearanceSection
	)
	default ControlAnchor anchor()
	{
		return ControlAnchor.BELOW;
	}

	@ConfigItem(
		keyName = "layout",
		name = "Arrangement",
		description = "Run the controls side by side or stack them vertically.",
		position = 1,
		section = appearanceSection
	)
	default ControlLayout layout()
	{
		return ControlLayout.HORIZONTAL;
	}

	@ConfigItem(
		keyName = "buttonSize",
		name = "Button size",
		description = "Width and height of each button.",
		position = 2,
		section = appearanceSection
	)
	@Range(min = 10, max = 48)
	@Units(Units.PIXELS)
	default int buttonSize()
	{
		return 16;
	}

	@ConfigItem(
		keyName = "sliderLength",
		name = "Slider length",
		description = "How long the slider track is. Ignored when the controls are buttons only.",
		position = 3,
		section = appearanceSection
	)
	@Range(min = 20, max = 200)
	@Units(Units.PIXELS)
	default int sliderLength()
	{
		return 32;
	}

	@ConfigItem(
		keyName = "xOffset",
		name = "Horizontal nudge",
		description = "Shifts the controls right (or left, if negative) from where they land by default.",
		position = 4,
		section = appearanceSection
	)
	@Range(min = -200, max = 200)
	@Units(Units.PIXELS)
	default int xOffset()
	{
		return 10;
	}

	@ConfigItem(
		keyName = "yOffset",
		name = "Vertical nudge",
		description = "Shifts the controls down (or up, if negative) from where they land by default.",
		position = 5,
		section = appearanceSection
	)
	@Range(min = -200, max = 200)
	@Units(Units.PIXELS)
	default int yOffset()
	{
		return -10;
	}

	@ConfigItem(
		keyName = "opacity",
		name = "Opacity",
		description = "How solid the controls are drawn.",
		position = 6,
		section = appearanceSection
	)
	@Range(min = 10, max = 100)
	@Units(Units.PERCENT)
	default int opacity()
	{
		return 80;
	}

	@ConfigItem(
		keyName = "zoomInHotkey",
		name = "Zoom in",
		description = "Key that zooms the minimap in.",
		position = 0,
		section = keyboardSection
	)
	default Keybind zoomInHotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "zoomOutHotkey",
		name = "Zoom out",
		description = "Key that zooms the minimap out.",
		position = 1,
		section = keyboardSection
	)
	default Keybind zoomOutHotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "resetHotkey",
		name = "Reset zoom",
		description = "Key that puts the zoom back to the game default.",
		position = 2,
		section = keyboardSection
	)
	default Keybind resetHotkey()
	{
		return Keybind.NOT_SET;
	}
}

