package com.minimapzoomcontrols;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.text.DecimalFormat;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;

class MinimapZoomControlsOverlay extends Overlay
{
	// the minimap draw area under each of the three toplevel layouts: resizable
	// with stones, resizable classic, and fixed. Only one is ever loaded.
	private static final int[] MINIMAP_DRAW_AREAS = {
		InterfaceID.ToplevelOsrsStretch.MINIMAP,
		InterfaceID.ToplevelPreEoc.MINIMAP,
		InterfaceID.Toplevel.MINIMAP,
	};

	private static final int ARC = 8;

	// roughly one tick per this many pixels of track, so a short slider gets a
	// readable handful rather than a smear
	private static final int TICK_SPACING = 8;
	private static final int MAX_TICKS = 10;

	// sampled off the game's own stone widgets: a pale rim over a warm grey face
	// that falls off towards the bottom, with everything recessed drawn near black
	private static final Color RIM = new Color(200, 189, 158);
	private static final Color SHADOW = new Color(43, 38, 30);
	private static final Color FACE_TOP = new Color(104, 98, 84);
	private static final Color FACE_BOTTOM = new Color(58, 54, 45);
	private static final Color FACE_TOP_LIT = new Color(133, 125, 106);
	private static final Color FACE_BOTTOM_LIT = new Color(80, 74, 62);
	private static final Color GLYPH = new Color(219, 208, 178);
	private static final Color GLYPH_DISABLED = new Color(118, 112, 96);
	private static final Color GROOVE = new Color(38, 33, 26);
	private static final Color TICK = new Color(96, 88, 70);

	private static final DecimalFormat ZOOM_FORMAT = new DecimalFormat("0.##");

	private final Client client;
	private final MinimapZoomControlsConfig config;
	private final TooltipManager tooltipManager;

	// laid out on the client thread during render, hit tested from the AWT
	// thread when a click comes in, so it is swapped rather than mutated
	private volatile ControlBounds bounds = ControlBounds.empty();

	@Inject
	MinimapZoomControlsOverlay(Client client, MinimapZoomControlsConfig config, TooltipManager tooltipManager)
	{
		this.client = client;
		this.config = config;
		this.tooltipManager = tooltipManager;

		// a dynamic overlay is handed the canvas untranslated, so the controls can
		// be drawn at the minimap's own coordinates
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Rectangle minimap = minimapBounds();
		if (minimap == null)
		{
			bounds = ControlBounds.empty();
			return null;
		}

		ControlBounds laidOut = ControlBounds.layout(minimap, config.anchor(), config.layout(), config.style(),
			config.buttonSize(), config.sliderLength(), config.xOffset(), config.yOffset());
		bounds = laidOut;

		double zoom = client.getMinimapZoom();
		net.runelite.api.Point mousePosition = client.getMouseCanvasPosition();
		Point mouse = new Point(mousePosition.getX(), mousePosition.getY());
		int alpha = config.opacity() * 255 / 100;

		if (laidOut.getTrack() != null)
		{
			drawTrack(graphics, laidOut, zoom, alpha);
		}

		for (Map.Entry<ZoomControl, Rectangle> button : laidOut.getButtons().entrySet())
		{
			ZoomControl control = button.getKey();
			Rectangle box = button.getValue();
			boolean available = control.isAvailable(zoom);
			boolean hovered = box.contains(mouse);

			drawButton(graphics, box, control, available, hovered, alpha);

			if (hovered && config.showTooltips())
			{
				tooltipManager.add(new Tooltip(control.getTooltip() + " (" + formatZoom(zoom) + ")"));
			}
		}

		if (config.showTooltips() && laidOut.trackContains(mouse))
		{
			tooltipManager.add(new Tooltip("Minimap zoom (" + formatZoom(zoom) + ")"));
		}

		return null;
	}

	ControlBounds getControls()
	{
		return bounds;
	}

	void clearControls()
	{
		bounds = ControlBounds.empty();
	}

	private Rectangle minimapBounds()
	{
		for (int component : MINIMAP_DRAW_AREAS)
		{
			Widget widget = client.getWidget(component);
			if (widget == null || widget.isHidden())
			{
				continue;
			}

			Rectangle widgetBounds = widget.getBounds();
			if (!widgetBounds.isEmpty())
			{
				return widgetBounds;
			}
		}

		return null;
	}

	private void drawButton(Graphics2D graphics, Rectangle box, ZoomControl control, boolean available,
		boolean hovered, int alpha)
	{
		drawStone(graphics, box, hovered && available, alpha);

		int inset = Math.max(4, box.width / 4);
		int centreX = box.x + box.width / 2;
		int centreY = box.y + box.height / 2;

		graphics.setColor(ColorUtil.colorWithAlpha(available ? GLYPH : GLYPH_DISABLED, alpha));
		graphics.setStroke(new BasicStroke(Math.max(2f, box.width / 8f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		graphics.drawLine(box.x + inset, centreY, box.x + box.width - inset - 1, centreY);
		if (control == ZoomControl.IN)
		{
			graphics.drawLine(centreX, box.y + inset, centreX, box.y + box.height - inset - 1);
		}
	}

	/**
	 * A raised stone face: pale rim, a darker line seated just inside it, and a
	 * face that falls off towards the bottom.
	 */
	private void drawStone(Graphics2D graphics, Rectangle box, boolean lit, int alpha)
	{
		graphics.setPaint(new GradientPaint(
			box.x, box.y, ColorUtil.colorWithAlpha(lit ? FACE_TOP_LIT : FACE_TOP, alpha),
			box.x, box.y + box.height, ColorUtil.colorWithAlpha(lit ? FACE_BOTTOM_LIT : FACE_BOTTOM, alpha)));
		graphics.fillRoundRect(box.x, box.y, box.width, box.height, ARC, ARC);

		graphics.setStroke(new BasicStroke(1f));
		graphics.setColor(ColorUtil.colorWithAlpha(SHADOW, alpha));
		graphics.drawRoundRect(box.x + 1, box.y + 1, box.width - 3, box.height - 3, ARC - 2, ARC - 2);
		graphics.setColor(ColorUtil.colorWithAlpha(RIM, alpha));
		graphics.drawRoundRect(box.x, box.y, box.width - 1, box.height - 1, ARC, ARC);
	}

	private void drawTrack(Graphics2D graphics, ControlBounds laidOut, double zoom, int alpha)
	{
		Rectangle track = laidOut.getTrack();

		graphics.setColor(ColorUtil.colorWithAlpha(GROOVE, alpha));
		graphics.fillRoundRect(track.x, track.y, track.width, track.height, ARC, ARC);
		graphics.setStroke(new BasicStroke(1f));
		graphics.setColor(ColorUtil.colorWithAlpha(RIM, alpha));
		graphics.drawRoundRect(track.x, track.y, track.width - 1, track.height - 1, ARC, ARC);

		drawTicks(graphics, track, laidOut.isVertical(), alpha);

		Rectangle handle = laidOut.handleAt(MinimapZoom.fraction(zoom));
		graphics.setColor(ColorUtil.colorWithAlpha(GLYPH, alpha));
		graphics.fillRoundRect(handle.x, handle.y, handle.width, handle.height, 4, 4);
		graphics.setColor(ColorUtil.colorWithAlpha(SHADOW, alpha));
		graphics.drawRoundRect(handle.x, handle.y, handle.width - 1, handle.height - 1, 4, 4);
	}

	private void drawTicks(Graphics2D graphics, Rectangle track, boolean vertical, int alpha)
	{
		graphics.setColor(ColorUtil.colorWithAlpha(TICK, alpha));

		int travel = vertical ? track.height : track.width;
		int ticks = Math.max(2, Math.min(MAX_TICKS, travel / TICK_SPACING));

		if (vertical)
		{
			int length = Math.max(2, track.width / 3);
			int right = track.x + track.width - 2;
			for (int i = 1; i < ticks; i++)
			{
				int y = track.y + i * track.height / ticks;
				graphics.drawLine(right - length, y, right, y);
			}
		}
		else
		{
			int length = Math.max(2, track.height / 3);
			int bottom = track.y + track.height - 2;
			for (int i = 1; i < ticks; i++)
			{
				int x = track.x + i * track.width / ticks;
				graphics.drawLine(x, bottom - length, x, bottom);
			}
		}
	}

	private static String formatZoom(double zoom)
	{
		return ZOOM_FORMAT.format(zoom / MinimapZoom.DEFAULT) + "x";
	}
}

