	OUT("Zoom out", -1),
	;

	private final String tooltip;
	private final int direction;

	double step(double zoom, double stepSize)
	{
		return MinimapZoom.step(zoom, stepSize, direction);
	}

	boolean isAvailable(double zoom)
	{
		return MinimapZoom.canStep(zoom, direction);
	}
