import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Where the controls sit relative to the minimap draw area.
 */
@Getter
@RequiredArgsConstructor
public enum ControlAnchor
{
	BELOW("Below minimap")
	{
		@Override
		Point origin(Rectangle minimap, int width, int height)
		{
			return new Point(centreX(minimap, width), minimap.y + minimap.height + EDGE_GAP);
		}
	},
	ABOVE("Above minimap")
	{
		@Override
		Point origin(Rectangle minimap, int width, int height)
		{
			return new Point(centreX(minimap, width), minimap.y - height - EDGE_GAP);
		}
	},
	TOP_LEFT("Top left")
	{
		@Override
		Point origin(Rectangle minimap, int width, int height)
		{
			return new Point(minimap.x, minimap.y);
		}
	},
	TOP_RIGHT("Top right")
	{
		@Override
		Point origin(Rectangle minimap, int width, int height)
		{
			return new Point(minimap.x + minimap.width - width, minimap.y);
		}
	},
	BOTTOM_LEFT("Bottom left")
	{
		@Override
		Point origin(Rectangle minimap, int width, int height)
		{
			return new Point(minimap.x, minimap.y + minimap.height - height);
		}
	},
	BOTTOM_RIGHT("Bottom right")
	{
		@Override
		Point origin(Rectangle minimap, int width, int height)
		{
			return new Point(minimap.x + minimap.width - width, minimap.y + minimap.height - height);
		}
	},
	;

	private static final int EDGE_GAP = 3;

	private final String displayName;

	abstract Point origin(Rectangle minimap, int width, int height);

	private static int centreX(Rectangle minimap, int width)
	{
		return minimap.x + (minimap.width - width) / 2;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

