package com.minimapzoomcontrols;

import com.google.inject.Provides;
import java.awt.event.MouseEvent;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;

@PluginDescriptor(
	name = "Minimap Zoom Controls",
	description = "Adds buttons or a slider to the minimap so it can be zoomed without a scroll wheel",
	tags = {"minimap", "zoom", "accessibility", "buttons", "slider", "scroll", "wheel"}
)
public class MinimapZoomControlsPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private MinimapZoomControlsConfig config;

	@Inject
	private MinimapZoomControlsOverlay overlay;

	private boolean restoreZoomDisabled;
	private boolean draggingSlider;

	private final MouseAdapter mouseAdapter = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent event)
		{
			ControlBounds controls = visibleControls();
			if (controls == null)
			{
				return event;
			}

			ZoomControl control = controls.controlAt(event.getPoint());
			boolean onTrack = controls.trackContains(event.getPoint());
			if (control == null && !onTrack)
			{
				return event;
			}

			if (!SwingUtilities.isLeftMouseButton(event))
			{
				return event;
			}

			if (control != null)
			{
				zoom(control);
			}
			else
			{
				draggingSlider = true;
				setZoomFrom(controls, event.getPoint());
			}

			event.consume();
			return event;
		}

		@Override
		public MouseEvent mouseDragged(MouseEvent event)
		{
			if (!draggingSlider)
			{
				return event;
			}

			// keep tracking once the cursor wanders off the groove, the way any
			// other slider does — fractionAt clamps to the ends
			ControlBounds controls = visibleControls();
			if (controls == null || controls.getTrack() == null)
			{
				draggingSlider = false;
				return event;
			}

			setZoomFrom(controls, event.getPoint());
			event.consume();
			return event;
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent event)
		{
			if (draggingSlider)
			{
				draggingSlider = false;
				event.consume();
				return event;
			}

			return swallowOverControls(event);
		}

		@Override
		public MouseEvent mouseClicked(MouseEvent event)
		{
			return swallowOverControls(event);
		}

		// the press has already been acted on; letting the rest of the click
		// through would walk the player to wherever the controls sit over the map
		private MouseEvent swallowOverControls(MouseEvent event)
		{
			if (!SwingUtilities.isLeftMouseButton(event))
			{
				return event;
			}

			ControlBounds controls = visibleControls();
			if (controls != null
				&& (controls.controlAt(event.getPoint()) != null || controls.trackContains(event.getPoint())))
			{
				event.consume();
			}

			return event;
		}
	};

	private final HotkeyListener zoomInHotkey = new HotkeyListener(() -> config.zoomInHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			zoom(ZoomControl.IN);
		}
	};

	private final HotkeyListener zoomOutHotkey = new HotkeyListener(() -> config.zoomOutHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			zoom(ZoomControl.OUT);
		}
	};

	private final HotkeyListener resetHotkey = new HotkeyListener(() -> config.resetHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			resetZoom();
		}
	};

	@Provides
	MinimapZoomControlsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MinimapZoomControlsConfig.class);
	}

	@Override
	protected void startUp()
	{
		// the client only honours a custom zoom level while its zoomed minimap
		// drawing is switched on, which is normally the Minimap plugin's doing.
		// Turn it on ourselves so the buttons work without that plugin.
		restoreZoomDisabled = !client.isMinimapZoom();
		client.setMinimapZoom(true);

		overlayManager.add(overlay);
		mouseManager.registerMouseListener(mouseAdapter);
		keyManager.registerKeyListener(zoomInHotkey);
		keyManager.registerKeyListener(zoomOutHotkey);
		keyManager.registerKeyListener(resetHotkey);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		mouseManager.unregisterMouseListener(mouseAdapter);
		keyManager.unregisterKeyListener(zoomInHotkey);
		keyManager.unregisterKeyListener(zoomOutHotkey);
		keyManager.unregisterKeyListener(resetHotkey);
		overlay.clearControls();
		draggingSlider = false;

		if (restoreZoomDisabled)
		{
			client.setMinimapZoom(false);
		}
	}

	private ControlBounds visibleControls()
	{
		return client.getGameState() == GameState.LOGGED_IN ? overlay.getControls() : null;
	}

	private void setZoomFrom(ControlBounds controls, java.awt.Point point)
	{
		double zoom = MinimapZoom.fromFraction(controls.fractionAt(point));
		clientThread.invoke(() -> client.setMinimapZoom(zoom));
	}

	private void zoom(ZoomControl control)
	{
		clientThread.invoke(() -> client.setMinimapZoom(control.step(client.getMinimapZoom(), config.zoomStep().getSize())));
	}

	private void resetZoom()
	{
		clientThread.invoke(() -> client.setMinimapZoom(MinimapZoom.DEFAULT));
	}
}

