/**
 * Screen positions of everything the plugin draws. Built on the client thread
 * while rendering and read from the AWT thread when a click arrives, so an
 * instance is never modified once handed out.
 */
final class ControlBounds
{
	private static final ControlBounds EMPTY = new ControlBounds(Collections.emptyMap(), null, false);

	private static final int GAP = 3;

	private static final int HANDLE_LIP = 2;

	@Getter
	private final Map<ZoomControl, Rectangle> buttons;

	/** The slider groove, or null when the controls are buttons only. */
	@Getter
	private final Rectangle track;

	@Getter
	private final boolean vertical;

	private ControlBounds(Map<ZoomControl, Rectangle> buttons, Rectangle track, boolean vertical)
	{
		this.buttons = buttons;
		this.track = track;
		this.vertical = vertical;
	}

	static ControlBounds empty()
	{
		return EMPTY;
	}

	static ControlBounds layout(Rectangle minimap, ControlAnchor anchor, ControlLayout arrangement,
		ControlStyle style, int size, int trackLength, int xOffset, int yOffset)
	{
		boolean vertical = arrangement == ControlLayout.VERTICAL;
		int trackSpan = style.hasTrack() ? trackLength + GAP : 0;
		int span = size * 2 + GAP + trackSpan;
		int width = vertical ? size : span;
		int height = vertical ? span : size;

		Point origin = anchor.origin(minimap, width, height);
		int x = origin.x + xOffset;
		int y = origin.y + yOffset;

		// zoom in leads when stacked and trails when side by side, so the pair
		// reads as + above - and as - before + the way map controls usually do
		Map<ZoomControl, Rectangle> laidOut = new EnumMap<>(ZoomControl.class);
		Rectangle track = null;
		if (vertical)
		{
			laidOut.put(ZoomControl.IN, new Rectangle(x, y, size, size));
			laidOut.put(ZoomControl.OUT, new Rectangle(x, y + span - size, size, size));
			if (style.hasTrack())
			{
				int thickness = trackThickness(size);
				track = new Rectangle(x + (size - thickness) / 2, y + size + GAP, thickness, trackLength);
			}
		}
		else
		{
			laidOut.put(ZoomControl.OUT, new Rectangle(x, y, size, size));
			laidOut.put(ZoomControl.IN, new Rectangle(x + span - size, y, size, size));
			if (style.hasTrack())
			{
				int thickness = trackThickness(size);
				track = new Rectangle(x + size + GAP, y + (size - thickness) / 2, trackLength, thickness);
			}
		}

		return new ControlBounds(laidOut, track, vertical);
	}

	ZoomControl controlAt(Point point)
	{
		for (Map.Entry<ZoomControl, Rectangle> button : buttons.entrySet())
		{
			if (button.getValue().contains(point))
			{
				return button.getKey();
			}
		}

		return null;
	}

	boolean trackContains(Point point)
	{
		return track != null && track.contains(point);
	}

	/**
	 * How far along the track a point sits, from 0 at the zoomed out end to 1 at
	 * the zoomed in end. Vertical tracks run bottom to top.
	 */
	double fractionAt(Point point)
	{
		if (track == null)
		{
			return 0d;
		}

		double travel = vertical
			? (track.y + track.height - point.y) / (double) track.height
			: (point.x - track.x) / (double) track.width;

		return Math.max(0d, Math.min(1d, travel));
	}

	Rectangle handleAt(double fraction)
	{
		if (track == null)
		{
			return null;
		}

		if (vertical)
		{
			int thickness = handleThickness(track.width);
			int offset = (int) Math.round((1d - fraction) * (track.height - thickness));
			return new Rectangle(track.x - HANDLE_LIP, track.y + offset, track.width + HANDLE_LIP * 2, thickness);
		}

		int thickness = handleThickness(track.height);
		int offset = (int) Math.round(fraction * (track.width - thickness));
		return new Rectangle(track.x + offset, track.y - HANDLE_LIP, thickness, track.height + HANDLE_LIP * 2);
	}

	private static int trackThickness(int size)
	{
		return Math.max(6, size * 3 / 4);
	}

	private static int handleThickness(int across)
	{
		return Math.max(4, across / 2);
	}
}

